    MC,
    /**
     * German prompt (+audio), pick the English.
     */
    REVERSED,
    /**
     * Audio prompt, pick the German.
     */
    AUDIO_MC,
    /**
     * English prompt, type the German.
     */
    TYPING,
    /**
     * Audio prompt, type what you hear.
     */
    HEARING,
